  s['blocks'][-1]=dict(kind='code',title='Точные изменения проверочной копии и просмотр журнала',code="SELECT source_row,name FROM stg_stock WHERE source_row=2;\nSELECT source_row,quantity FROM stg_orders WHERE source_row=2;\nUPDATE stg_stock SET name='Несуществующая модель' WHERE source_row=2;\nUPDATE stg_orders SET quantity='0' WHERE source_row=2;\n-- Выполнить 03_import.sql целиком. Ожидается отказ.\nSELECT source_file,source_row,issue_code,reason FROM import_issue\nWHERE disposition='отклонено' ORDER BY source_file,source_row;\nSELECT COUNT(*) FROM product;\n-- Ожидаются stock_link и quantity_price, счётчик 0.\n-- Вернуть записанные исходные name и quantity в stg_строки.\nCALL import_checked();")
